<?php
class Auditoria {
 public static function tipos(){return array('configuracion_editada'=>'Configuración administrativa','metodo_pago_editado'=>'Método de pago configurado','ticket_en_espera'=>'Ticket en espera','ticket_descartado'=>'Ticket pendiente descartado','producto_creado'=>'Producto creado','producto_editado'=>'Producto editado','usuario_creado'=>'Usuario creado','usuario_editado'=>'Usuario editado','rol_creado'=>'Rol creado','permisos_editados'=>'Permisos modificados','minimo_configurado'=>'Mínimo configurado','ajuste_inventario'=>'Ajuste de inventario','traspaso'=>'Traspaso','merma'=>'Merma','cancelacion'=>'Cancelación','devolucion'=>'Devolución','gasto'=>'Gasto registrado');}
 private static function limpiar($value){if(!is_array($value))return $value;$out=array();foreach($value as $key=>$v){if($key!=='contrasena_modificada'&&preg_match('/contrasen|password|hash|csrf|token|secret|clave/i',(string)$key))continue;$out[$key]=self::limpiar($v);}return $out;}
 public static function usuario(array $u){return array_intersect_key($u,array_flip(array('id','nombre','nombre_usuario','rol_id','rol_nombre','activo')));}
 public static function producto(PDO $db,$id){
  $q=$db->prepare('SELECT id,nombre,descripcion,categoria_id,unidad_base_id,impuesto_id,tipo_producto,precio_incluye_impuesto,controla_inventario,activo FROM productos WHERE id=?');$q->execute(array($id));$p=$q->fetch();if(!$p)return null;$q=$db->prepare('SELECT id,sku,nombre,costo,precio,stock_minimo,activo FROM variantes_producto WHERE producto_id=? ORDER BY id');$q->execute(array($id));$p['variantes']=$q->fetchAll();$q=$db->prepare('SELECT id,ruta,orden,es_principal FROM imagenes_producto WHERE producto_id=? ORDER BY orden,id');$q->execute(array($id));$p['imagenes']=$q->fetchAll();return $p;
 }
 public static function registrar(PDO $db,$actorId,$tipo,$referencia,$resumen,$antes,$despues,array $extra=array(),$origen='cambio',$origenId=null,$fecha=null,$historico=false,$nombreOriginal=null){
  if(!array_key_exists($tipo,self::tipos()))throw new LogicException('Tipo de auditoría no registrado.');if(!$db->inTransaction())throw new LogicException('La auditoría requiere la transacción de la operación.');
  $antes=self::limpiar($antes);$despues=self::limpiar($despues);$extra=self::limpiar($extra);if($antes===$despues&&!$extra)return;
  $name='Sistema';$login=null;if($actorId!==null){$q=$db->prepare('SELECT nombre,nombre_usuario FROM usuarios WHERE id=?');$q->execute(array($actorId));$u=$q->fetch();$name=$nombreOriginal!==null?$nombreOriginal:($u?$u['nombre']:'Usuario no disponible');$login=$u?$u['nombre_usuario']:null;}
  $details=json_encode(array('antes'=>$antes,'despues'=>$despues,'contexto'=>$extra),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($details===false||strlen($details)>1048576)throw new RuntimeException('No se pudo guardar el detalle de auditoría.');
  $sql='INSERT INTO bitacora_actividad(usuario_id,usuario_nombre,usuario_login,tipo,referencia,resumen,detalle,origen,origen_id,historico,creado_en) VALUES(?,?,?,?,?,?,?,?,?,?,'.($fecha===null?'CURRENT_TIMESTAMP':'FROM_UNIXTIME(?)').')';$values=array($actorId,$name,$login,$tipo,(string)$referencia,$resumen,$details,$origen,$origenId,$historico?1:0);if($fecha!==null)$values[]=$fecha;
  try{$db->prepare($sql)->execute($values);}catch(PDOException $e){if($origenId!==null&&isset($e->errorInfo[1])&&(int)$e->errorInfo[1]===1062){$q=$db->prepare('SELECT id FROM bitacora_actividad WHERE origen=? AND origen_id=?');$q->execute(array($origen,$origenId));if($q->fetchColumn())return;}throw $e;}
 }
 public static function operacion(PDO $db,$source,$id,$historico=false){
  $map=array('ajuste'=>'ajustes_inventario','almacen'=>'operaciones_almacen','reembolso'=>'devoluciones_venta','gasto'=>'gastos');if(!isset($map[$source]))throw new LogicException('Origen no admitido.');$q=$db->prepare('SELECT *,UNIX_TIMESTAMP(creado_en) fecha_unix FROM '.$map[$source].' WHERE id=?');$q->execute(array($id));$r=$q->fetch();if(!$r)throw new LogicException('Documento de auditoría no encontrado.');$before=null;$after=null;$context=array();$name=null;
  if($source==='ajuste'){
   $result=json_decode($r['resultado'],true);if(!is_array($result)||!isset($result['movimiento_id']))return;$q=$db->prepare('SELECT m.variante_id,v.sku,p.nombre producto,l.nombre ubicacion,m.tipo_referencia,m.notas FROM movimientos_inventario m JOIN variantes_producto v ON v.id=m.variante_id JOIN productos p ON p.id=v.producto_id JOIN ubicaciones l ON l.id=m.ubicacion_id WHERE m.id=?');$q->execute(array($result['movimiento_id']));$m=$q->fetch();if(!$m)return;$type='ajuste_inventario';$ref='Ajuste '.$id;$summary=$m['producto'].' · '.$m['sku'];$before=array('existencia'=>$result['cantidad_anterior']);$after=array('existencia'=>$result['cantidad_nueva']);$context=$m;$context['cambio']=$result['cambio'];
  }elseif($source==='almacen'){
   $result=json_decode($r['resultado'],true);if(!is_array($result))return;$q=$db->prepare('SELECT v.sku,p.nombre producto,lo.nombre origen,ld.nombre destino FROM variantes_producto v JOIN productos p ON p.id=v.producto_id LEFT JOIN ubicaciones lo ON lo.id=? LEFT JOIN ubicaciones ld ON ld.id=? WHERE v.id=?');$q->execute(array($r['origen_id'],$r['destino_id'],$r['variante_id']));$m=$q->fetch();if(!$m)return;$type=$r['tipo'];$ref=$r['folio'];$summary=$m['producto'].' · '.$m['sku'];$before=array('existencia_origen'=>$result['origen_anterior'],'existencia_destino'=>$result['destino_anterior']);$after=array('existencia_origen'=>$result['origen_nuevo'],'existencia_destino'=>$result['destino_nuevo']);$context=$m;$context['cantidad']=$r['cantidad'];$context['motivo']=$r['motivo'];
  }elseif($source==='reembolso'){
   $d=$r['datos']?json_decode($r['datos'],true):array();$type=$r['tipo'];$ref=$r['folio'];$summary='Ticket '.(isset($d['venta_folio'])?$d['venta_folio']:$r['venta_id']);$name=isset($d['usuario_nombre'])?$d['usuario_nombre']:null;$after=array('importe'=>$r['total'],'venta_id'=>$r['venta_id'],'tipo'=>$r['tipo']);$context=array('motivo'=>$r['motivo']);foreach(array('autorizado_por','autorizado_nombre','caja_nombre','ubicacion_nombre','venta_folio') as $k)if(isset($d[$k]))$context[$k]=$d[$k];
  }else{
   $d=json_decode($r['datos'],true);$type='gasto';$ref=$r['folio'];$summary=$r['descripcion'];$name=isset($d['usuario'])?$d['usuario']:null;$after=array('importe'=>$r['monto'],'fecha_gasto'=>$r['fecha'],'origen'=>$r['origen']);$context=array('concepto'=>$r['descripcion'],'beneficiario'=>$r['beneficiario'],'referencia'=>$r['referencia']);foreach(array('categoria','metodo','caja') as $k)if(isset($d[$k]))$context[$k]=$d[$k];
  }
  self::registrar($db,$r['usuario_id'],$type,$ref,$summary,$before,$after,$context,$source,$id,$r['fecha_unix'],$historico,$name);
 }
}
